target.css:
:root {
  --ink: #20332d;
  --muted: #63766e;
  --paper: #fffdf5;
  --moss: #315e4d;
  --mint: #dceee1;
  --line: #c8ddd0;
  --amber: #e8aa45;
  --amber-pale: #fff0ca;
  --sky: #dcecf0;
}

* {
  box-sizing: border-box;
}

.grow-board {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.board-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  background: var(--moss);
  color: var(--paper);
}

.chamber-mark {
  display: grid;
  width: 34px;
  height: 34px;
  margin: 0;
  place-items: center;
  font-size: 20px;
  background: var(--mint);
  border-radius: 11px;
}

.head-copy {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 1px;
}

.head-copy .eyebrow {
  color: var(--mint);
}

.grow-board h1,
.grow-board h2 {
  margin: 0;
}

.grow-board h1 {
  font-size: 19px;
  line-height: 1.1;
}

.live-pill,
.tiny-tag,
.queue-count,
.stage {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.live-pill {
  padding: 6px 8px;
  color: var(--moss);
  background: var(--mint);
  border-radius: 999px;
}

.board-body {
  display: grid;
  grid-template-columns: 0.84fr 1.16fr;
  gap: 10px;
  padding: 11px 14px;
}

.climate-card,
.flush-card {
  border: 1px solid var(--line);
  border-radius: 12px;
}

.climate-card {
  padding: 10px;
  background: var(--mint);
}

.panel-title,
.flush-card > header,
.action-bar,
.flush-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.grow-board h2 {
  font-size: 14px;
  line-height: 1.1;
}

.tiny-tag {
  padding: 4px 6px;
  color: var(--moss);
  background: var(--paper);
  border-radius: 5px;
}

.climate-readings,
.flush-list {
  padding: 0;
  margin: 8px 0 0;
  list-style: none;
}

.reading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 6px 0;
  border-top: 1px solid var(--line);
}

.reading span,
.strain small {
  color: var(--muted);
  font-size: 11px;
}

.reading strong {
  font-size: 15px;
  line-height: 1;
}

.flush-card {
  padding: 10px;
  background: var(--paper);
}

.flush-card > header {
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.flush-card .eyebrow {
  color: var(--muted);
}

.queue-count {
  color: var(--muted);
}

.flush-list {
  margin-top: 0;
}

.flush-row {
  min-height: 31px;
  border-bottom: 1px solid var(--line);
}

.flush-row:last-child {
  border-bottom: 0;
}

.strain {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.strain b {
  font-size: 12px;
  line-height: 1.1;
}

.stage {
  padding: 4px 6px;
  border-radius: 5px;
}

.ready {
  color: var(--moss);
  background: var(--mint);
}

.soon {
  color: var(--ink);
  background: var(--amber-pale);
}

.mist {
  color: var(--moss);
  background: var(--sky);
}

.action-bar {
  min-height: 42px;
  padding: 8px 14px;
  background: var(--amber-pale);
  border-top: 1px solid var(--line);
}

.action-bar p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.action-bar p b {
  color: var(--ink);
}

.action-bar button {
  padding: 7px 10px;
  color: var(--paper);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  background: var(--moss);
  border: 0;
  border-radius: 7px;
}

